(function(){"use strict";importScripts("https://cdnjs.cloudflare.com/ajax/libs/crypto-js/4.2.0/crypto-js.min.js"),self.onmessage=function(t){const{encryptedData:r,ivHex:c,keyHex:o,id:s}=t.data;try{const e=CryptoJS.enc.Hex.parse(o),p=CryptoJS.enc.Hex.parse(c),a=CryptoJS.enc.Base64.parse(r),n=CryptoJS.lib.CipherParams.create({ciphertext:a}),i=CryptoJS.AES.decrypt(n,e,{iv:p,mode:CryptoJS.mode.CBC,padding:CryptoJS.pad.Pkcs7}).toString(CryptoJS.enc.Utf8);self.postMessage({id:s,success:!0,data:i})}catch(e){self.postMessage({id:s,success:!1,error:e.message})}}})();
